import pandas as pd
import os
from datetime import datetime
from pandas.errors import EmptyDataError


def task_func(csv_file_path, column_name, date_format="%Y-%m-%d"):
    """Read a CSV, retain dates before now, and sort them chronologically."""
    if not os.path.exists(csv_file_path):
        raise FileNotFoundError(f"File not found: {csv_file_path}")

    try:
        data = pd.read_csv(csv_file_path)
    except EmptyDataError:
        return pd.DataFrame()

    if column_name not in data.columns:
        raise ValueError(f"Column {column_name!r} not found in CSV file")

    data[column_name] = pd.to_datetime(data[column_name], format=date_format)
    return data.loc[data[column_name] < datetime.now()].sort_values(column_name)

import pandas as pd
import itertools
import random


def task_func(colors, states):
    """Return shuffled Color:State combinations distributed across columns."""
    combinations = list(itertools.product(colors, states))
    random.shuffle(combinations)
    column_count = min(len(colors), len(states))
    return pd.DataFrame({
        f"Color:State {i + 1}": [
            f"{color}:{state}"
            for color, state in combinations[i::column_count]
        ]
        for i in range(column_count)
    })

