from collections import Counter
import os
import csv

FILE_DIR = './yourdictfiles/'


def task_func(output_file, test_directory):
    """Export whitespace-separated word counts and return the total, or 0 on error."""
    try:
        counts = Counter()
        for filename in os.listdir(test_directory):
            if filename.endswith('.txt'):
                path = os.path.join(test_directory, filename)
                if os.path.isfile(path):
                    with open(path, 'r', encoding='utf-8') as source:
                        counts.update(source.read().split())

        with open(output_file, 'w', newline='', encoding='utf-8') as destination:
            writer = csv.writer(destination)
            writer.writerow(['Word', 'Count'])
            writer.writerows(counts.items())
        return sum(counts.values())
    except Exception:
        return 0

