import pandas as pd
import matplotlib.pyplot as plt


def task_func(data):
    """Combine fruit sales, fill missing quantities with zero, and plot them."""
    for record in data:
        for value in record.values():
            if not isinstance(value, int):
                if not pd.api.types.is_scalar(value) or not pd.isna(value):
                    raise TypeError('Sales quantities must be integers or missing values')

    sales = pd.DataFrame(data).fillna(0)
    ax = sales.plot(kind='line', title='Fruit Sales over Time')
    ax.set_xlabel('Time')
    ax.set_ylabel('Sales Quantity')
