import json
import pandas as pd
import numpy as np
from collections import defaultdict


def task_func(input_file="data.json"):
    """Return sorted per-key means and medians of numeric JSON values."""
    with open(input_file, "r") as file:
        records = json.load(file)

    values = defaultdict(list)
    for record in records:
        for key, value in record.items():
            column = values[key]
            if isinstance(value, (int, float)) and not np.isnan(value):
                column.append(value)

    keys = sorted(values)
    statistics = []
    for key in keys:
        column = values[key]
        if column:
            statistics.append((np.mean(column), np.median(column)))
        else:
            statistics.append((np.nan, np.nan))

    return pd.DataFrame(statistics, index=keys, columns=["mean", "median"])

