import pandas as pd
from statistics import mean


def task_func(df: pd.DataFrame) -> dict:
    """Return a generator yielding (name, average score) for each unique name."""
    if 'Name' not in df.columns or 'Score' not in df.columns:
        raise ValueError("DataFrame must contain 'Name' and 'Score' columns")

    def generate(name, scores):
        yield name, mean(scores)

    return {
        name: generate(name, group['Score'].tolist())
        for name, group in df.groupby('Name', sort=True)
    }

