import pandas as pd
from itertools import cycle
from random import randint, seed


def task_func(
    n_grades,
    students=['Alice', 'Bob', 'Charlie', 'David', 'Eve'],
    grade_range=range(1, 11),
    rng_seed=None
):
    """Generate a grade report, cycling through the supplied students."""
    if not students:
        raise ValueError('The list of students must not be empty.')
    if rng_seed is not None:
        seed(rng_seed)

    student_cycle = cycle(students)
    rows = [
        (next(student_cycle), grade_range[randint(0, len(grade_range) - 1)])
        for _ in range(n_grades)
    ]
    return pd.DataFrame(rows, columns=['Student', 'Grade'])

import csv
import os


def task_func(data, file_path, headers):
    """Write headers and tuple rows to CSV, padding short rows with None."""
    if file_path is None:
        raise ValueError('file_path must not be None')

    with open(file_path, 'w', newline='') as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow(headers)
        for row in data:
            padded_row = row + (None,) * max(0, len(headers) - len(row))
            writer.writerow(padded_row)

    return os.path.abspath(file_path)

import collections
import operator
import os
import shutil


def task_func(data_dict, source_directory, backup_directory):
    """Update the dictionary, count its values, and back up source files."""
    data_dict['a'] = 1
    counts = collections.Counter(data_dict.values())
    value_frequencies = sorted(
        counts.items(), key=operator.itemgetter(1), reverse=True
    )

    try:
        os.makedirs(backup_directory, exist_ok=True)
        for name in os.listdir(source_directory):
            source = os.path.join(source_directory, name)
            if os.path.isfile(source):
                shutil.copy2(source, os.path.join(backup_directory, name))
    except OSError:
        backup_status = False
    else:
        backup_status = True

    return data_dict, value_frequencies, backup_status

